window.renderCompanionCase=(t,href)=>`<section class="project-header"><div class="project-title"><h1 class="page-title">${t('阿里巴巴<br>陪伴假主题传播','Alibaba<br>Companionship leave')}</h1></div><div class="project-info"><dl><div><dt>${t('项目 / 品牌','Project / Brand')}</dt><dd>${t('阿里巴巴','Alibaba')}</dd></div><div><dt>${t('项目形式','Format')}</dt><dd>${t('ESG 报告系列 / 公众号互动长图','ESG report series / Interactive WeChat editorial')}</dd></div><div><dt>${t('服务类别','Category')}</dt><dd>${t('新媒体传播与内容创意','Digital & Social Content')}</dd></div><div><dt>${t('服务内容','Services')}</dt><dd>${t('员工沟通 / 长图视觉 / 互动呈现','Employee communication / Editorial design / Interactive presentation')}</dd></div></dl><div class="project-description"><span class="number">${t('项目介绍','About the project')}</span><p>${t('作为阿里巴巴 ESG 报告系列传播中的一篇，本作品聚焦“陪伴假”及员工关怀，以员工生活中的真实情境串联福利实践。通过橙绿配色、富有节奏的文字编排与动态长图，将报告中与员工相关的内容转化为亲切、易读的公众传播。','Part of Alibaba’s ESG report communication series, this editorial focuses on companionship leave and employee care. Everyday employee stories, orange and green typography and an animated long-form layout make the report’s people-related content accessible and relatable.')}</p></div></div></section><section class="companion-stage"><div class="companion-device"><div class="companion-status" aria-hidden="true"><i></i></div><iframe src="assets/companion/original.html?v=paths-2" title="${t('陪伴假互动恢复预览','Companionship leave interactive preview')}" sandbox="allow-same-origin"></iframe></div><div class="companion-note"><p>${t('在手机内上下滚动，查看完整作品。','Scroll inside the phone to explore the full piece.')}</p><div class="companion-actions"><button data-companion-restart>${t('重新体验','Restart')}</button></div></div></section><section class="companion-highlights"><header><h2>${t('把员工关怀，写进生活日常。','Employee care, told through everyday life.')}</h2><p>${t('从日常情境切入，以橙绿文字节奏与点击互动，展开“陪伴假”的福利故事。','Everyday situations, orange-and-green typography and click interactions unfold the story of companionship leave.')}</p></header><div class="companion-detail-grid"><figure><img src="assets/companion/detail-1.webp" loading="lazy" alt="情境开篇 · 用对话引入"><figcaption>${t('情境开篇 · 用对话引入','A conversation to begin')}</figcaption></figure><figure><img src="assets/companion/detail-2.webp" loading="lazy" alt="文字节奏 · 让重点跳出来"><figcaption>${t('文字节奏 · 让重点跳出来','Typography with rhythm')}</figcaption></figure><figure><img src="assets/companion/detail-3.webp" loading="lazy" alt="生活故事 · 让福利有温度"><figcaption>${t('生活故事 · 让福利有温度','Benefits through lived stories')}</figcaption></figure><figure><img src="assets/companion/detail-4.webp" loading="lazy" alt="主题收束 · 回到陪伴的价值"><figcaption>${t('主题收束 · 回到陪伴的价值','Back to the value of companionship')}</figcaption></figure></div></section><section class="companion-qr-footer"><img src="assets/companion/wechat-qr.png" alt="扫码查看公众号原文"><p>${t('扫一扫，在公众号浏览','Scan to view on WeChat')}</p></section><section class="next-project"><a href="${href('work')}">↖ ${t('返回全部案例','Back to all projects')}</a><a href="${href('project','&id=fliggy')}"><span>${t('下一个项目','Next project')}</span><strong>${t('飞猪｜长期信息图传播设计合作','Fliggy｜An ongoing infographic design partnership')} ↗</strong></a></section>`;
document.addEventListener('DOMContentLoaded',()=>{const frame=document.querySelector('.companion-device iframe');if(!frame)return;document.querySelectorAll('[data-companion-mode]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-companion-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));frame.src='assets/companion/'+b.dataset.companionMode}));document.querySelector('[data-companion-restart]').addEventListener('click',()=>frame.src=frame.src)});
